  depth: vec4f,                 // near, far, reversed A, reversed B: z = B/d - A
  surface: vec4f,               // CPU-double ellipsoid c, atmosphere c, height, reserved
  moonDirectionWC: vec4f,       // camera-to-Moon unit direction, angular radius rad
